rowdata.pyStepsJavaSource:
// If creating an output page when all goes well isn't desired then we must
// clear it at the start, because callers will use @OperationFail() afterwards
// and we wouldn't want an incorrect result because of a page from a previous op.
if (tools.getParamValue("OutputPageName").equals(""))
   tools.putParamValue("OutputPageName", "pyOutput");
ClipboardPage op = tools.findPage(tools.getParamValue("OutputPageName"));
if (op != null) {
   op.getProperty("pyStatus").clearValue();
   op.getProperty("pyErrors").removeFromClipboard();
}

try {
   // We call isLocked to get the pxCreateDateTime
   ClipboardPage lockPage = tools.createPage("System-Locks", "");
   if (tools.getDatabase().getLockManager().isLocked(myStepPage, lockPage))
   {
      lockGone = false;
      lockUpdateTime = lockPage.getString(".pxUpdateDateTime");
      if (lockUpdateTime.equals(""))
          lockUpdateTime = lockPage.getString(".pxCreateDateTime");
   }
   else
   {
      lockGone = true;
      lockUpdateTime = "";
   }
} catch (DatabaseException e) {
   myStepPage.addMessage(e.getMessage());
   nextBlock = "Out";
}

boolean bAssignmentCorrupted = false;
ClipboardPage workPage = tools.getPrimaryPage();
String assign_FlowName = myStepPage.getString(".pxFlowName");
if (assign_FlowName.equals(""))
	bAssignmentCorrupted = true;

if (!bAssignmentCorrupted)
{
	ClipboardProperty flowRef = workPage.getIfPresent(".pxFlow(" + assign_FlowName + ")");
	if (flowRef == null)
		bAssignmentCorrupted = true;
	else
	{
		ClipboardPage flowPage = flowRef.getPageValue();

		// If the pxFlow page's interest page starts with the workpage name itself, just clip it
		String flowInterestPage = flowPage.getString(".pyFlowInterestPage");
		if (!flowInterestPage.equals("") && flowInterestPage.charAt(0) != '.')
		{
			int dotIdx = flowInterestPage.indexOf(".");
			if (dotIdx == -1)
				flowInterestPage = ""; // It was just the page name
			else
				flowInterestPage = flowInterestPage.substring(dotIdx+1);
		}

		// If the assignment page's interest page starts with the workpage name itself, just clip it
		String assignInterestPage = myStepPage.getString(".pyInterestPage");
		if (!assignInterestPage.equals("") && assignInterestPage.charAt(0) != '.')
		{
			int dotIdx = assignInterestPage.indexOf(".");
			if (dotIdx == -1)
				assignInterestPage = ""; // It was just the page name
			else
				assignInterestPage = assignInterestPage.substring(dotIdx+1);
		}

		// Now they should be equal
		if (!(assignInterestPage.equals(flowInterestPage)))
			bAssignmentCorrupted = true;
	}
}

if (bAssignmentCorrupted)
{
	// First, remove the assignment from the clipboard
	myStepPage.removeFromClipboard();

	// Next, add a message to the work page
	workPage.addMessage("\t[@baseclass.pyMessageLabel]AssignmentCorrupted");

	// Then jump to Out
	nextBlock = "Out";
}

ClipboardPage pgInterestPage = myStepPage;
ClipboardPage assignPage = tools.findPage(tools.getParamValue("assignPage"));
if (assignPage == null)
{
	// Previous steps already check for the presense of the assignment page, so this should never happen.
   	tools.putParamValue("pyErrorMessage",tools.getLocalizedTextForString("pyMessageLabel","AssignmentCorrupted"));
    tools.putParamValue("pyStatus",pega_procom_processenginestatus.StatusFailAssignmentNoLongerAvailable());
  	return true;
}

ClipboardProperty pyAssignActions = assignPage.getProperty("pyAssignActions");


// The validateActionName parameter, if set, says that we only allow this flow action to be processed if the
// assignment/case has declared it, so it has to be in pyAssignActions
if ("true".equals(tools.getParamValue("validateActionName")))
{
  	if (pyAssignActions.size() == 0)
	{
      	// We need to check that this specific action is declared for the assignment, flow, stage, or case.  We populate
      	// pyAssignActions with only this flow action to save time.
    	tools.putParamValue("GetSpecificAction",tools.getParamValue("actionName"));
		pega_procom_pegaprocomutilities.populateFlowActions(assignPage, myStepPage, tools);
		pyAssignActions = tools.findPage(tools.getParamValue("assignPage")).getProperty("pyAssignActions");
    }

	if (pega_rules_utilities.IsInPageList(tools.getParamValue("actionName"),".pyActionName", pyAssignActions) == false)
    {
 		tools.putParamValue("pyErrorMessage",tools.getLocalizedTextForString("pyMessageLabel","FlowActionNotInAssignActions\t"+tools.getParamValue("actionName")));
		tools.putParamValue("pyStatus",pega_procom_processenginestatus.statusInvalidFlowAction());
        return true;
    }
}


// if the assignment is on an embedded page, we need to know whether this is a case-wide action or not.  Case-wide (and stage) actions always
// use the top level page of the work object.
if (!interestPage.equals(""))
{
  	boolean localCase = false;  
	if (pyAssignActions.size() == 0)
    {
      	// We don't need to populate all actions, just the stage & case ones. 
		ParameterPage instParamsPage = new ParameterPage();
		instParamsPage.putString("CurrentStage",tools.getPrimaryPage().getString("pxCurrentStage"));
		com.pegarules.generated.pega_rules_utilities.pxCallCaseType(tools.getStepPage(), "STAGE_GETACTIONS", instParamsPage);
  		if (tools.findPage("pyCaseActionsList") != null)
        {
			pyAssignActions = tools.findPage("pyCaseActionsList").getProperty("pxResults");
  			if (pega_rules_utilities.IsInPageList(tools.getParamValue("actionName"),".pyActionName",pyAssignActions) == true)
				localCase=true;
		}
	} 
  	else
	{
      	// Note that if the action specified is NOT present in pyAssignActions, we assume it is a local assignment action, not case.
		java.util.Iterator iter = pyAssignActions.iterator();
		while (iter.hasNext())
		{
			ClipboardProperty assignAction = (ClipboardProperty)iter.next();
			ClipboardPage pgAction = assignAction.getPageValue();

			if (tools.getParamValue("TaskStatus").equals(pgAction.getString(".pyActionName")))
			{
				localCase = pgAction.getString(".pyActionType").equals("LocalCase");
				break;
			}
		}
    }

  	if (!localCase)
    	pgInterestPage = tools.findPage(interestPage);
}


if("".equals(tools.getParamValue("pyErrorMessage")))
{
	// We have to call the flow action passing the current parameter page because it puts the following parameters
	// on the parameter page: keepWorkingOnSame, keepWorkingOnSameFlow, keepWorkingOnSameCover, confirmHarness
	tools.putParamValue("pyFlowActionPurpose", "VALIDATE");

	StringMap flowAction = new HashStringMap();
	flowAction.putString("pxObjClass", "Rule-Obj-FlowAction");
	flowAction.putString("pyClassName", pgInterestPage.getClassName());
	flowAction.putString("pyActionName", tools.getParamValue("actionName"));

	try {
		tools.doAction(flowAction, pgInterestPage, tools.getParameterPage());
	} catch (com.pega.pegarules.pub.generator.RuleNotFoundException rnfe) {	
		tools.putParamValue("pyErrorMessage", rnfe.getMessage());
		tools.putParamValue("pyStatus", pega_procom_processenginestatus.statusFail());
	} catch (PRRuntimeError re) {	
		tools.putParamValue("pyErrorMessage", re.getMessage());
		tools.putParamValue("pyStatus", pega_procom_processenginestatus.statusFailExceptionThrown());
		tools.putParamValue("pyStackTrace", pega_rules_utilities.getStackTrace(re));		
	} catch (PRRuntimeException pre) {
		// If the user doesn't have the security to run this flow action, a PRRuntimeException is thrown.
		// We will catch that and put the error onto the output page.
		tools.putParamValue("pyErrorMessage", pre.getMessage());
		tools.putParamValue("pyStatus", pega_procom_processenginestatus.statusFailFlowActionSecurity());
	} finally {
		tools.putParamValue("pyFlowActionPurpose", "");
	}
}

// Use whichever of the following 3, if set, is the most recent:
// the lock's update time, the assignment's create time, or its update time

String strAssignCreateTime = myStepPage.getString(".pxCreateDateTime");
String strAssignUpdateTime = myStepPage.getString(".pxUpdateDateTime");

// First check if the assignment has an update date time (set only when a local
// action is saved).
if (!strAssignUpdateTime.equals("")) {
   if (pega_rules_datetime.DateTimeDifference(lockUpdateTime, strAssignUpdateTime, "s") > 0)
      lockUpdateTime = strAssignUpdateTime;

} else {
   if (pega_rules_datetime.DateTimeDifference(lockUpdateTime, strAssignCreateTime, "s") > 0)
      lockUpdateTime = strAssignCreateTime;
}

// Call CompleteAssigment, catching all possible errors
try {
	tools.putParamValue("TaskStatus", tools.getParamValue("actionName"));
	tools.putParamValue("WorkObjectPageName", tools.getPrimaryPage().getName());
	pega_rules_utilities.callActivity(myStepPage, "CompleteAssignment", tools.getParameterPage());

	// Note that we check OperationFail() in the transition, so if any
	// activity called by CompleteAssignment (post-processing, flow
	// utility, etc.) was an api that set the output page and there was
	// a fail, we will use that page to return to the caller and abort.
	// Note also that we check OperationFail() first.  If a fail occurred
	// and then later on the flow threw an exception (caught below),
	// we want to report the first failure, since that is more helpful.

} catch (ActivityTerminateException e) {
	throw e;
} catch (Throwable e) {
	if (e instanceof PRRuntimeError)  
		tools.putParamValue("pyErrorMessage", e.getMessage());
	else if (e instanceof PRRuntimeException)
		tools.putParamValue("pyErrorMessage", e.getMessage());
	else if (e instanceof PRAppRuntimeException)
		tools.putParamValue("pyErrorMessage", e.getMessage());
	else
		// the java errors & exceptions, like NullPointerException, don't have a message
		// so we have to use toString instead
		tools.putParamValue("pyErrorMessage", e.toString());
	tools.putParamValue("pyStackTrace", pega_rules_utilities.getStackTrace(e));
}
